import React, { useEffect, useRef } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const ProductAndServices = () => {
  const cardsRef = useRef([]);

  useEffect(() => {
    const cards = gsap.utils.toArray(cardsRef.current);
    
    // Set initial properties for each card
    cards.forEach((card, i) => {
      gsap.set(card, { opacity: 0, y: 100 }); // Start hidden and below
    });

    // Create ScrollTriggers for each card
    cards.forEach((card, i) => {
      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: card,
          start: "top bottom", // When the top of the card reaches the bottom of the viewport
          end: "bottom top", // When the bottom of the card reaches the top of the viewport
          scrub: true, // Smooth scrubbing
          markers: false, // Change to true to debug
        },
      });

      tl.to(card, { opacity: 1, y: 0, duration: 0.5 }) // Fade in and move to position
        .to(card, { opacity: 0, duration: 0.5 }, "+=0.5"); // Fade out after a delay
    });

    // Pin the first card
    ScrollTrigger.create({
      trigger: cards[0],
      start: "top top",
      end: "+=300%", // Adjust to control how long the first card stays pinned
      pin: true,
      anticipatePin: 1,
    });

    // Clean up on unmount
    return () => {
      ScrollTrigger.getAll().forEach((trigger) => trigger.kill());
    };
  }, []);

  return (
    <section className="relative bg-primary-light border-t border-b border-blue-300" id="product">
      <div className="container mx-auto">
        <h2 className="text-3xl font-bold text-center mb-8 text-white">PRODUCTS & SERVICES</h2>

        <div className="relative">
          {/* First Card */}
          <div ref={(el) => (cardsRef.current[0] = el)} className="h-screen flex items-center justify-center">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700">
              <img className="object-cover w-full rounded-t-lg md:h-auto md:w-96 md:rounded-none md:rounded-s-lg" src="./images/Cricket.jpg" alt="Cricket Image" />
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">MATCH GRAPHICS</h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">Our Match Graphics service is designed to bring real-time, data-driven visuals...</p>
              </div>
            </div>
          </div>

          {/* Second Card */}
          <div ref={(el) => (cardsRef.current[1] = el)} className="h-screen flex items-center justify-center">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700">
              <img className="object-cover w-full rounded-t-lg md:h-auto md:w-96 md:rounded-none md:rounded-s-lg" src="./images/Cricket2.jpg" alt="Cricket Image" />
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">LIVE STATS</h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">Our live stats service provides comprehensive, real-time statistics...</p>
              </div>
            </div>
          </div>

          {/* Third Card */}
          <div ref={(el) => (cardsRef.current[2] = el)} className="h-screen flex items-center justify-center">
            <div className="flex flex-col items-center bg-white border border-gray-200 rounded-lg shadow md:flex-row md:max-w-4xl mx-auto hover:bg-gray-100 dark:border-gray-700 dark:bg-gray-800 dark:hover:bg-gray-700">
              <img className="object-cover w-full rounded-t-lg md:h-auto md:w-96 md:rounded-none md:rounded-s-lg" src="./images/Cricket3.jpg" alt="Cricket Image" />
              <div className="flex flex-col justify-between p-4 leading-normal h-full">
                <h5 className="mb-2 text-2xl font-bold tracking-tight text-gray-900 dark:text-white">TEAM LINEUPS</h5>
                <p className="mb-3 font-normal text-gray-700 dark:text-gray-400">Display complete team lineups dynamically in your broadcasts for better engagement...</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default ProductAndServices;
